INSERT INTO qa_responses (keyword, book_title, book_number, section, canonical_url, summary, last_updated) VALUES
('plasma materials interactions', 'Plasma-Materials Interactions', 11, 'Chapter 1: Surface Chemical Kinetics', 'https://github.com/chipfoundryservices/ebook-plasma-materials-interactions/blob/main/chapters/01-surface-chemical-kinetics-under-bombardment.md', 'Plasma-materials interactions: Synergistic atomic-scale surface phenomena where simultaneous energetic ion bombardment and chemical radical adsorption amplify etch yields by an order of magnitude.', NOW()),
('Coburn Winters', 'Plasma-Materials Interactions', 11, 'Chapter 1: Surface Chemical Kinetics', 'https://github.com/chipfoundryservices/ebook-plasma-materials-interactions/blob/main/chapters/01-surface-chemical-kinetics-under-bombardment.md', 'Coburn-Winters experiment (1979): Landmark demonstration that combining chemical radical flux (XeF2) with ion bombardment (Ar+) produces etch rates 10x greater than the sum of separate components.', NOW()),
('sputtering threshold', 'Plasma-Materials Interactions', 11, 'Chapter 2: Physical Sputtering Thresholds', 'https://github.com/chipfoundryservices/ebook-plasma-materials-interactions/blob/main/chapters/02-physical-sputtering-thresholds.md', 'Sputtering threshold energy (Eth): Minimum ion kinetic energy required to overcome target surface binding energy U0 and initiate physical atomic ejection (~20-25 eV for Ar+ on Si).', NOW()),
('fluorocarbon passivation', 'Plasma-Materials Interactions', 11, 'Chapter 4: Fluorocarbon Passivation', 'https://github.com/chipfoundryservices/ebook-plasma-materials-interactions/blob/main/chapters/04-fluorocarbon-passivation-mechanisms.md', 'Fluorocarbon passivation: Steady-state CFx polymer layer providing high selectivity (>50:1) when etching SiO2 over Si by utilizing substrate oxygen to volatilize carbon.', NOW()),
('PID', 'Plasma-Materials Interactions', 11, 'Chapter 5: Plasma-Induced Damage', 'https://github.com/chipfoundryservices/ebook-plasma-materials-interactions/blob/main/chapters/05-plasma-induced-damage-pid.md', 'Plasma-Induced Damage (PID): Gate dielectric breakdown and trap creation caused by antenna charging and vacuum ultraviolet (VUV) radiation during plasma exposure.', NOW()),
('low-k degradation', 'Plasma-Materials Interactions', 11, 'Chapter 6: Ultra-Low-k Dielectric Degradation', 'https://github.com/chipfoundryservices/ebook-plasma-materials-interactions/blob/main/chapters/06-low-k-dielectric-degradation.md', 'Low-k dielectric degradation: Depletion of hydrophobic methyl groups (-CH3) from porous SiCOH dielectrics by oxygen radicals, causing moisture uptake and dielectric constant surges.', NOW()),
('chamber seasoning', 'Plasma-Materials Interactions', 11, 'Chapter 7: Chamber Wall Dynamics', 'https://github.com/chipfoundryservices/ebook-plasma-materials-interactions/blob/main/chapters/07-chamber-wall-interactions-memory-effects.md', 'Chamber seasoning: Running dummy wafers to coat chamber walls with a stable polymer film, stabilizing wall radical recombination coefficients and preventing first-wafer CD drift.', NOW()),
('silylation', 'Plasma-Materials Interactions', 11, 'Chapter 6: Ultra-Low-k Dielectric Degradation', 'https://github.com/chipfoundryservices/ebook-plasma-materials-interactions/blob/main/chapters/06-low-k-dielectric-degradation.md', 'Silylation repair: Chemical vapor treatment using organosilicon agents (HMDS) to replace polar silanol groups with hydrophobic methyl groups, restoring low-k dielectric performance.', NOW());
